node --env-file=.env.local -e '
function redact(url) {
  if (!url) return null;
  const u = new URL(url);
  return { protocol: u.protocol.replace(":",""), host: u.hostname, port: u.port || "5432", database: u.pathname.replace(/^\//,""), user: u.username, hasPassword: Boolean(u.password) };
}
console.log(JSON.stringify({
  DATABASE_URL: redact(process.env.DATABASE_URL),
  DATAFN_DATABASE_URL: redact(process.env.DATAFN_DATABASE_URL),
  DATAFN_INSOUTH_DATABASE_URL: redact(process.env.DATAFN_INSOUTH_DATABASE_URL),
  DATAFN_USEAST_DATABASE_URL: redact(process.env.DATAFN_USEAST_DATABASE_URL),
  DATAFN_EUWEST_DATABASE_URL: redact(process.env.DATAFN_EUWEST_DATABASE_URL)
}, null, 2));
'

ls -la .env.local .env.dev .env.example && node --env-file=.env.local -e '
function redact(url) {
  if (!url) return null;
  const u = new URL(url);
  return { protocol: u.protocol.replace(":",""), host: u.hostname, port: u.port || "5432", database: u.pathname.replace(/^\//,""), user: decodeURIComponent(u.username), hasPassword: Boolean(u.password) };
}
console.log(JSON.stringify({
  DATABASE_URL: redact(process.env.DATABASE_URL),
  DATAFN_DATABASE_URL: redact(process.env.DATAFN_DATABASE_URL)
}, null, 2));
' && (test -f /tmp/nucleum-backend-local.log && echo "LOG_EXISTS" && wc -l /tmp/nucleum-backend-local.log || echo "LOG_MISSING")

node --env-file=.env.local --input-type=module -e '
import postgres from "postgres";
async function probe(name, url) {
  const sql = postgres(url, { connect_timeout: 3, max: 1 });
  const started = Date.now();
  try {
    const rows = await sql`select current_database() as db, current_user as usr`;
    console.log(JSON.stringify({ name, ok: true, ms: Date.now()-started, db: rows[0].db, user: rows[0].usr }));
  } catch (error) {
    console.log(JSON.stringify({ name, ok: false, ms: Date.now()-started, code: error.code, message: error.message }));
  } finally {
    await sql.end({ timeout: 1 }).catch(() => {});
  }
}
await probe("DATABASE_URL", process.env.DATABASE_URL);
await probe("DATAFN_DATABASE_URL", process.env.DATAFN_DATABASE_URL);
'

